TreeNode* searchBSTBrute(TreeNode* root, int val) {
    if (!root) return nullptr;
    if (root->val == val) return root;
    TreeNode* left = searchBSTBrute(root->left, val);            // check EVERY node, both subtrees
    if (left) return left;
    return searchBSTBrute(root->right, val);
}

